//! Byte-compatible implementations of the Rails signing, encryption and serialization contracts
//! Ember depends on, and of the Rails formats more than one crate writes (`ActiveSupport::JSON`,
//! `Content-Disposition`). They are verified against golden vectors generated by the reference app
//! (`vectors/rails_compat.json`, produced by `reference-tools/rails_compat_vectors.rb`, and the
//! filenames in `vectors/storage.json`), and what they generate is checked by Rails itself
//! (`reference-tools/rails_compat_verify_rust.rb`). Also the [`clock::Clock`] the crates above it
//! read `Time.current` from.
//!
//! The public signatures below are the interface other crates build against.

pub mod clock;
pub mod content_disposition;
pub mod cookies;
pub mod encoding;
pub mod env;
pub mod global_id;
pub mod json;
pub mod key_generator;
